import re
import json

def detect_anaphoric_ambiguity(text):
    # Define a regular expression pattern to match pronouns
    pattern = r'\b(a|an|the|it|its|this|that|these|those|he|she|her|him|his|they|them|their|itself|oneself|someone|something|anyone|anything|everyone|everything|no one|nothing|someone|something|anyone|anything|everyone|everything)\b'

    # Find all matches of the pattern in the text
    matches = re.finditer(pattern, text)

    # Initialize an empty list to store the results
    results = []

    # Iterate over the matches
    for match in matches:
        # Get the matched text and its start and end offsets
        pronoun = match.group()
        start = match.start()
        end = match.end()

        # Check if the pronoun's antecedent is unclear or contested
        if pronoun in ['it', 'its', 'this', 'that', 'these', 'those', 'he', 'she', 'her', 'him', 'his', 'they', 'them', 'their']:
            # If the pronoun's antecedent is unclear or contested, add the result to the list
            results.append({"start": start, "end": end, "label": "anaphoric_ambiguity"})

    # Return the list of results
    return results

